const SCN_SE1={"Imminent": {"body": ["Players using Imminent Deployment may only activate and deploy Groups with L and M Tonnage in the 1st round. From the start of the 2nd round onwards, they may activate Groups of H tonnage. From the start of the 3rd round onwards, they may activate any Group."]}, "Backline": {"body": ["Players using Backline Deployment may only activate and deploy Groups of H and C Tonnage the 1st round. From the start of the 2nd round onwards, they may activate any Group. Groups with the Vanguard-X special rule may use it as normal."]}, "Staggered": {"body": ["Players using Staggered Deployment can only activate and deploy X Groups of their choice in the 1st round. Then they must activate and deploy an additional X Groups of their choice in the 2nd round. They must activate and deploy any remaining Groups in the 3rd round. Groups with the Vanguard-X special rule may use it as normal.", "For Skirmish games, X is 1. For Clash games, X is 2. For Battle games, X is 3. For Reconquest games, X is 4 plus 1 for every 1000 points above 3001."]}, "Normal Scoring": {"body": ["Players are awarded the corresponding High Scoring when they Control a Scenario Objective and the corresponding Low Scoring when they Contest a Scenario Objective."], "table": {"head": ["Dropsite Size", "High Scoring", "Low Scoring"], "rows": [["Small", "2VP", "0VP"], ["Medium", "3VP", "1VP"], ["Large", "4VP", "2VP"]]}, "after": ["Normal Scoring awards VP during the Victory Points step of the End Phase on rounds 4 and 6."]}, "Demolish Scoring": {"body": ["Using the Normal Scoring table, players are immediately awarded the corresponding High Scoring when they have Levelled a Dropsite. Using the Normal Scoring table, players are immediately awarded the corresponding Low Scoring when they have Ruined a Dropsite."]}, "Focal Points Scoring": {"body": ["Players total up the specified value of their Ships in range of the Focal Point. The players with the highest combined value within that distance gains 3VP. Any other player with at least half of that value within range of that Focal point gains 1VP. When calculating value, Ships use their High Value unless otherwise specified and Ships assigned an Admiral always use their High Value. Ships only count as being in a single Focal Point, if a Ship would be in range of two or more focal points, choose one for it to count towards."], "table": {"head": ["Dropsite Size", "High Value", "Low Value"], "rows": [["Light", "1", "0"], ["Medium", "4", "1"], ["Heavy", "7", "3"], ["Colossal", "11", "5"]]}, "after": ["Focal Points award VP during the Victory Points step of the End Phase on rounds 4 and 6."]}, "Kill Points Scoring": {"body": ["Players are awarded 2VP at the end of the game for every 500 points of Ships and Admirals they have destroyed."]}, "Assess Scoring": {"body": ["While on General Quarters, any Capital Ship within 6” of a Scenario Dropsite may choose to Assess that Dropsite before or after its movement. If it does, it cannot attack and cannot launch assets. Each Dropsite can only be Assessed by each player once and each Dropsite Assessed awards the Assessing player 1VP."]}};
const SCN_RULEBOOK={"11.1": {"heading": "Control & Contest", "body": ["Players Control a Dropsite if <b>only they </b>have Battalions and/or any Features they have deployed on it. If only allied players have Battalions/deployed Features on it, those players must choose who Controls it.", "Players Contest a Dropsite if <b>they and an opponent</b> have Battalions and/or deployed Features on it.", "Players that destroy a Dropsite have <b>Levelled</b> it.", "Dropsites that have less than half of their Hull Points remaining are <b>Ruined</b>."]}, "11.2": {"heading": "Damaging Dropsites", "body": ["Dropsites use the best Save available out of those on their Features (so a Dropsite with a Military Outpost has an Energy Save of 3+). Once a feature has been removed, any saves that feature would grant cannot be used.", "For every 4 damage a Dropsite takes from an <b>attacking Group or Asset/s attacks</b>, the attacking player may instead remove one Feature and any Battalions assigned to it from that Dropsite instead of dealing that damage.", "<b>When a Dropsite has been reduced to 0 Hull Points, it is destroyed.</b> Remove all Battalions from that Dropsite. If that Dropsite is a Space Station, remove it from the board. Destroyed Dropsites cannot have assets assigned to them and all Features on them are removed and do not count for any scoring."]}, "12.3": {"heading": "Secondary Objectives", "body": ["Choose two Secondary Objectives when building your Fleet. These can be completed during the game and award additional VP for completing them.", "When you complete a Secondary Objective, declare it. At the end of the game, you may choose <b>one</b> of your Secondary Objectives to gain VP from.", "<b>Secondary Objectives that require you to nominate something must be declared to all opponents prior to the 1st Planning Phase of the game.</b>"]}, "12.3.4": {"heading": "Annihilate", "body": ["You are awarded 1VP at the end of the game for every 500 points of Ships and Admirals you have destroyed. A maximum of 3VP may be scored using this Secondary Objective."]}, "12.3.5": {"heading": "Take Prizes", "body": ["You are awarded 1VP at the end of the game for every 100 points of Ships you have captured. A maximum of 3VP may be scored using this Secondary Objective."]}, "12.3.7": {"heading": "Decapitate", "body": ["You are awarded 2VP if you kill your opponent’s highest-Level Admiral (or one of if there are multiple with the same Level)."]}, "12.4": {"heading": "Kill Points & Ties", "body": ["Kill Points are the total points in Admirals and Ships you have destroyed. In the event of a tie in VP, the victor is determined by who has the most Kill Points"]}};
